svg.metadata:
vec2 atA(float u) { float x = mix(237.0, 420.0, u); return vec2(x, 219.7000 + -106.9000 * smoothstep(251.0, 370.0, x)); }
vec2 atB(float u) { float x = mix(237.0, 391.5000, u); return vec2(x, 219.7000 + 109.3000 * smoothstep(251.0, 341.5000, x)); }
// a rack of 6 columns by 9 cells: rails, caps, four units with a status light each. act is 0 dark, 0.5 standing by,
// 1 serving; hit flashes its lights.
float rack(float col, float cell, float c0, float k0, float act, float hit, float ph, float s) {
  float lc = col - c0; float lr = cell - k0;
  if (lc < 0.0 || lc > 5.0 || lr < 0.0 || lr > 8.0) return 0.0;
  float frame = 0.2 + 0.26 * min(act * 2.0, 1.0);
  if (lc < 0.5 || lc > 4.5 || lr < 0.5 || lr > 7.5) return frame;
  if (mod(lr, 2.0) < 0.5) return 0.0;
  if (lc > 3.5) return mix(act, 1.1 + 0.4 * hit, sm(0.6, 0.9, act));
  return act * (0.68 + 0.08 * sin(2.0 * ph + hash(vec2(lr + s, lc)) * 30.0));
}
// a flash of width w round time s, on the cycle: the nearer of s and its copy a cycle away
float at(float t, float s, float w) { float d = t - s; d -= T * floor(d / T + 0.5); return exp(-d * d / w); }
// a line's band, at least a column wide and a cell tall
float band(float d, float k) { return k * (1.0 - sm(3.6, 4.8, abs(d))); }
float field(vec2 p, float t) {
  if (p.x < 24.0 || p.x > 696.0 || p.y < 24.0 || p.y > 436.0) return 0.0;
  float ph = TAU * t / T;
  float col = floor((p.x - 4.0) / 7.0 + 0.5);
  float cell = floor(p.y / 9.4);
  float v = 0.0;
  // the regions' states: the primary boots, stands by, serves, loses power; the standby serves, stands down, takes over
  float pa = t < 1.0 ? sm(0.3, 0.8, t) : 1.0 - sm(2.8500, 3.1000, t);
  float actA = t < 1.0 ? 0.5 * sm(0.3, 0.8, t) : (0.5 + 0.5 * sm(1.6, 1.8, t)) * (1.0 - sm(2.8500, 3.1000, t));
  float actB = t < 2.6 ? 1.0 - 0.5 * sm(1.95, 2.2, t) : 0.5 + 0.5 * sm(3.3100, 3.5300, t);
  float flash = exp(-pow(t - 2.8800, 2.0) / 0.0012);
  float toA = sm(1.6, 1.7, t) * (1.0 - sm(3.3100, 3.4100, t));
  float hitA = 0.0; float hitB = 0.0;
  hitB += at(t, 0.5300, 0.006);
  hitB += at(t, 1.0925, 0.006);
  hitB += at(t, 1.6550, 0.006);
  hitA += at(t, 2.2175, 0.006);
  hitA += at(t, 2.7800, 0.006);
  hitB += at(t, 3.7600, 0.006);
  hitB += at(t, 3.9050, 0.006);
  hitB += at(t, 4.4675, 0.006);
  // the floors: faint ground; the primary's goes out with its power
  float hs = hash(floor(p / vec2(7.0, 9.4)) + 5.0);
  if (col >= 61.0 && col <= 89.0) {
    if (cell >= 5.0 && cell <= 18.0) v = max(v, step(0.62, hs) * (0.16 + 0.04 * sin(ph + hs * 40.0)) * pa + 0.6 * flash * step(0.62, hs));
    if (cell >= 28.0 && cell <= 41.0) v = max(v, step(0.62, hs) * (0.16 + 0.04 * sin(ph + hs * 40.0)));
  }
  v = max(v, rack(col, cell, 64.0, 8.0, actA, hitA, ph, 0.0) + 0.7 * flash * step(0.1, rack(col, cell, 64.0, 8.0, 1.0, 0.0, ph, 0.0)));
  v = max(v, rack(col, cell, 64.0, 31.0, actB, hitB, ph, 3.0));
  v = max(v, rack(col, cell, 73.0, 8.0, actA, 0.0, ph, 1.0) + 0.7 * flash * step(0.1, rack(col, cell, 73.0, 8.0, 1.0, 0.0, ph, 0.0)));
  v = max(v, rack(col, cell, 73.0, 31.0, actB, 0.0, ph, 4.0));
  v = max(v, rack(col, cell, 82.0, 8.0, actA, 0.0, ph, 2.0) + 0.7 * flash * step(0.1, rack(col, cell, 82.0, 8.0, 1.0, 0.0, ph, 0.0)));
  v = max(v, rack(col, cell, 82.0, 31.0, actB, 0.0, ph, 5.0));
  // the replication line: dotted, from the primary's floor to the standby's box; copies run from the serving region
  if (abs(p.x - 501.0) < 1.0 && p.y > 184.6000 && p.y < 241.2000) v = max(v, mod(cell, 2.0) < 0.5 ? 0.32 : 0.0);
  { float u = clamp((t - 0.8000) / 0.25, 0.0, 1.0); if (u > 0.0 && u < 1.0) v += blob(p, vec2(501.0, mix(229.2000, 190.6000, ease(u))), 7.0, 1.0 * sm(0.0, 0.15, u) * (1.0 - sm(0.85, 1.0, u))); }
  { float u = clamp((t - 1.0500) / 0.25, 0.0, 1.0); if (u > 0.0 && u < 1.0) v += blob(p, vec2(501.0, mix(229.2000, 190.6000, ease(u))), 7.0, 1.0 * sm(0.0, 0.15, u) * (1.0 - sm(0.85, 1.0, u))); }
  { float u = clamp((t - 1.3000) / 0.25, 0.0, 1.0); if (u > 0.0 && u < 1.0) v += blob(p, vec2(501.0, mix(229.2000, 190.6000, ease(u))), 7.0, 1.0 * sm(0.0, 0.15, u) * (1.0 - sm(0.85, 1.0, u))); }
  { float u = clamp((t - 2.0) / 0.25, 0.0, 1.0); if (u > 0.0 && u < 1.0) v += blob(p, vec2(501.0, mix(190.6000, 229.2000, ease(u))), 7.0, 1.0 * sm(0.0, 0.15, u) * (1.0 - sm(0.85, 1.0, u))); }
  { float u = clamp((t - 2.4000) / 0.25, 0.0, 1.0); if (u > 0.0 && u < 1.0) v += blob(p, vec2(501.0, mix(190.6000, 229.2000, ease(u))), 7.0, 1.0 * sm(0.0, 0.15, u) * (1.0 - sm(0.85, 1.0, u))); }
  // the users: a crowd of faint points that flicker, and the dotted way in to the router
  {
    vec2 d = (p - vec2(64.0, 219.7000)) / vec2(38.0, 100.0);
    if (length(d) < 1.0) v = max(v, step(0.6, hs) * (0.46 + 0.12 * sin(ph + hs * 50.0)) * (1.0 - 0.35 * length(d)));
  }
  if (abs(p.y - 219.7000) < 1.0 && p.x > 108.0 && p.x < 201.0) v = max(v, mod(col, 2.0) < 0.5 ? 0.3 : 0.0);
  // the router: a dense core in a ring, and its two branches; the one it sends down is lit
  v += blob(p, vec2(221.0, 219.7000), 13.0, 1.1 + 0.4 * exp(-pow(t - 3.3100, 2.0) / 0.003));
  v += 0.5 * exp(-pow(length(p - vec2(221.0, 219.7000)) - 22.0, 2.0) / 16.0);
  if (p.x > 237.0 && p.x < 420.0) v = max(v, band(p.y - atA(clamp((p.x - 237.0) / 183.0, 0.0, 1.0)).y, 0.26 + 0.32 * toA));
  if (p.x > 237.0 && p.x < 391.5000) v = max(v, band(p.y - atB(clamp((p.x - 237.0) / 154.5000, 0.0, 1.0)).y, 0.26 + 0.32 * (1.0 - toA)));
  // the requests: in from the crowd (one crosses the seam), then down a branch; the one sent to the dead primary is
  // turned back at its edge, and resent to the standby
  for (int j = 0; j < 8; j++) for (int w = 0; w <= 1; w++) {
    float a = 0.0800 + 0.5625 * float(j) + float(w) * T;
    float u = clamp((t - a + 0.35) / 0.35, 0.0, 1.0);
    if (u > 0.0 && u < 1.0) v += blob(p, vec2(mix(108.0, 207.0, u), 219.7000), 8.0, 1.15 * sm(0.0, 0.1, u));
  }
  { float u = clamp((t - 0.0800) / 0.4000, 0.0, 1.0); if (u > 0.0 && u < 1.0) v += blob(p, atB(ease(u)), 8.0, 1.15 * (1.0 - sm(0.9, 1.0, u))); }
  { float u = clamp((t - 0.6425) / 0.4000, 0.0, 1.0); if (u > 0.0 && u < 1.0) v += blob(p, atB(ease(u)), 8.0, 1.15 * (1.0 - sm(0.9, 1.0, u))); }
  { float u = clamp((t - 1.2050) / 0.4000, 0.0, 1.0); if (u > 0.0 && u < 1.0) v += blob(p, atB(ease(u)), 8.0, 1.15 * (1.0 - sm(0.9, 1.0, u))); }
  { float u = clamp((t - 1.7675) / 0.4000, 0.0, 1.0); if (u > 0.0 && u < 1.0) v += blob(p, atA(ease(u)), 8.0, 1.15 * (1.0 - sm(0.9, 1.0, u))); }
  { float u = clamp((t - 2.3300) / 0.4000, 0.0, 1.0); if (u > 0.0 && u < 1.0) v += blob(p, atA(ease(u)), 8.0, 1.15 * (1.0 - sm(0.9, 1.0, u))); }
  { float u = clamp((t - 2.8925) / 0.4000, 0.0, 1.0); if (u > 0.0 && u < 1.0) v += blob(p, atA(ease(u)), 8.0, 1.15);
    float b = clamp((t - 3.2925) / 0.18, 0.0, 1.0); if (b > 0.0 && b < 1.0) v += blob(p, atA(1.0) - vec2(22.0 * (1.0 - pow(1.0 - b, 3.0)), 0.0), 8.0, 1.15 * (1.0 - b));
    float r = clamp((t - 3.3100) / 0.4000, 0.0, 1.0); if (r > 0.0 && r < 1.0) v += blob(p, atB(ease(r)), 8.0, 1.15 * (1.0 - sm(0.9, 1.0, r))); }
  { float u = clamp((t - 3.4550) / 0.4000, 0.0, 1.0); if (u > 0.0 && u < 1.0) v += blob(p, atB(ease(u)), 8.0, 1.15 * (1.0 - sm(0.9, 1.0, u))); }
  { float u = clamp((t - 4.0175) / 0.4000, 0.0, 1.0); if (u > 0.0 && u < 1.0) v += blob(p, atB(ease(u)), 8.0, 1.15 * (1.0 - sm(0.9, 1.0, u))); }
  // the strip: a slot opens at the right as each request reaches the router, and fills, in its region's row, once
  // that request is served
  float n = 0.0;
  n += ease((t - 0.0800) / 0.3);
  n += ease((t - 0.6425) / 0.3);
  n += ease((t - 1.2050) / 0.3);
  n += ease((t - 1.7675) / 0.3);
  n += ease((t - 2.3300) / 0.3);
  n += ease((t - 2.8925) / 0.3);
  n += ease((t - 3.4550) / 0.3);
  n += ease((t - 4.0175) / 0.3);
  float k = cell - 5.0;
  if (p.x > 100.0 && p.x < 350.0 && k > -0.5 && k < 2.5 && mod(k, 2.0) < 0.5) {
    float q = floor(n - 1.0 - (330.0 - p.x) / 14.0 + 0.5);
    float cx = 330.0 - 14.0 * (n - 1.0 - q);
    if (abs(p.x - cx) < 3.5 && cx > 106.0 && cx < 344.0) {
      float j = mod(q, 8.0);
      float inA = (abs(j - 3.0) < 0.5 || abs(j - 4.0) < 0.5) ? 1.0 : 0.0;
      float s = j < 0.5 ? 0.4800 : j < 1.5 ? 1.0425 : j < 2.5 ? 1.6050 : j < 3.5 ? 2.1675 : j < 4.5 ? 2.7300 : j < 5.5 ? 3.7100 : j < 6.5 ? 3.8550 : 4.4175;
      float done = q < -0.5 ? 1.0 : sm(s, s + 0.06, t);
      float wt = clamp((cx - 106.0) / 14.0, 0.0, 1.0) * clamp((344.0 - cx) / 14.0, 0.0, 1.0);
      float mine = k < 0.5 ? inA : 1.0 - inA;
      v = max(v, wt * (0.18 + (mine * 0.92) * done));
    }
  }
  return v;
}
